 const diagrams=body.prompt.filter(b=>b.type==='diagram');assert.equal(diagrams.length,1);const fig=diagrams[0];assert.equal(fig.scene.kind,'source_figure');assert(fig.scene.kind==='source_figure');assert.equal(fig.scene.profile,'legacy-2019-change-timeline');assert.deepEqual(fig.scene.values,[0]);assert.equal(fig.caption,'図1 刷新プロジェクトのスケジュール');for(const phrase of['期間（月）','1から10','工程','設計は1〜2','プログラム開発は3〜6','結合試験は7〜8','総合試験は9〜10','右矢印','順に連続'])assert(fig.alt.includes(phrase));
 for(const phrase of['a1=プロジェクト管理チーム、a2=担当PM、a3=開発チーム','受付・取りまとめ・会議運営、内容確認・採否判断','プロジェクト計画に反映して更新','影響調査の指示や起票の経緯の確認','cは全ての開発チーム','13週目はプログラム開発工程','調査後に分かる','依頼先を事前にチーム1だけへ絞らない','400×10%=40kステップ',`40/10+40/${s.prod[1]}+40/${s.prod[2]}=${s.extra[0]}+${s.extra[1]}+${s.extra[2]}=${s.work}人月`,`総合試験も含めた${s.work+s.extra[3]}人月`,'eは32週目','33週目','37週目','17週目から32週目までの16週=4か月','17週目から36週目までの20週=5か月','毎週一定人数で全工程',`fは${s.work}/4を切り上げて${s.staff[0]}人`,`gは${s.work}/5を切り上げて${s.staff[1]}人`,'それより少ない人数','最多4人との比較',r.originalH[r.hPossibilities.findIndex(pair=>pair.every((p,i)=>p===s.possible[i]))],'総合試験は当初の期限内'])assert(body.explanation.includes(phrase),'Missing reason '+phrase);
